const data = $input.first().json.body || $input.first().json;

if (!data.message || typeof data.message !== 'string' || data.message.trim() === '') {
  throw new Error('Customer message is required.');
}

return [
  {
    json: {
      customer_name: data.customer_name || 'Unknown Customer',
      customer_email: data.customer_email || '',
      message: data.message.trim(),
      received_at: new Date().toISOString()
    }
  }
];

const aiResult = $input.first().json;

// Debug the AI result
console.log('AI Result in Prepare Ticket:', JSON.stringify(aiResult, null, 2));

// Direct mapping from category to department
const categoryToDepartment = {
  'billing': 'Billing',
  'technical': 'Technical Support',
  'account': 'Account Support',
  'general': 'Customer Service',
  'other': 'Customer Service'
};

const categoryToRouting = {
  'billing': 'Assigned to Billing',
  'technical': 'Assigned to Technical Support',
  'account': 'Assigned to Account Support',
  'general': 'Assigned to Customer Service',
  'other': 'Assigned for manual review'
};

const category = (aiResult.category || 'other').toLowerCase().trim();
const department = categoryToDepartment[category] || 'Customer Service';
const routing_note = categoryToRouting[category] || 'Assigned for manual review';

const customerData = $('Validate Customer Input').first().json;

return [{
  json: {
    ticket_id: 'TICKET-' + Date.now(),
    customer_name: customerData.customer_name || 'Unknown Customer',
    customer_email: customerData.customer_email || 'no-email@example.com',
    customer_message: customerData.message || 'No message provided',
    received_at: customerData.received_at || new Date().toISOString(),
    category: category,
    priority: aiResult.priority || 'low',
    sentiment: aiResult.sentiment || 'neutral',
    department: department,
    summary: aiResult.summary || 'No summary provided',
    suggested_response: aiResult.suggested_response || 'Thank you for your message.',
    status: 'Open',
    routing_note: routing_note
  }
}];

// Parse AI response
const aiResponse = $input.first().json;

// The AI might return the response in different formats
let parsedResult = {};

// Try to extract the JSON from the response
try {
  // Check if the response is already an object
  if (typeof aiResponse === 'object' && aiResponse !== null) {
    // Check if the response has the expected fields
    if (aiResponse.category) {
      parsedResult = aiResponse;
    } else {
      // The response might be nested
      const text = aiResponse.text || aiResponse.output || aiResponse.response || JSON.stringify(aiResponse);
      parsedResult = JSON.parse(text);
    }
  } else if (typeof aiResponse === 'string') {
    // Try to parse the string as JSON
    parsedResult = JSON.parse(aiResponse);
  } else {
    // Try to get the text content
    const text = aiResponse.text || aiResponse.output || aiResponse.response || '';
    if (text) {
      parsedResult = JSON.parse(text);
    }
  }
} catch (error) {
  console.error('Failed to parse AI response:', error);
  console.error('Raw response:', JSON.stringify(aiResponse));

  // Use fallback values
  parsedResult = {
    category: 'other',
    priority: 'low',
    sentiment: 'neutral',
    department: 'Customer Service',
    summary: 'Unable to parse AI response',
    suggested_response: 'We will review your request and get back to you shortly.'
  };
}

// Ensure all required fields exist
const defaults = {
  category: 'other',
  priority: 'low',
  sentiment: 'neutral',
  department: 'Customer Service',
  summary: 'No summary provided',
  suggested_response: 'Thank you for your message. A support representative will contact you shortly.'
};

// Merge with defaults for missing fields
const finalResult = { ...defaults, ...parsedResult };

// Clean up the values
finalResult.category = (finalResult.category || 'other').toLowerCase().trim();
finalResult.priority = (finalResult.priority || 'low').toLowerCase().trim();
finalResult.sentiment = (finalResult.sentiment || 'neutral').toLowerCase().trim();
finalResult.department = finalResult.department || 'Customer Service';
finalResult.summary = finalResult.summary || 'No summary provided';
finalResult.suggested_response = finalResult.suggested_response || 'Thank you for your message.';

// Log the final result
console.log('=== Parsed Result ===');
console.log(JSON.stringify(finalResult, null, 2));

return [{ json: finalResult }];
